import { __ } from 'i18n';
import { api, constants, u } from '@converse/headless';
import { html } from 'lit';
import tplTypeahead from 'shared/rich-composer/templates/typeahead.js';
import 'shared/chat/reply-preview.js';

const { CHATROOMS_TYPE } = constants;

/**
 * @param {import('../message-form').default} el
 */
export default (el) => {
    const composing_spoiler = el.model.get('composing_spoiler');
    const label_message = composing_spoiler ? __('Hidden message') : __('Message');
    const label_spoiler_hint = __('Optional hint');
    const message_limit = api.settings.get('message_limit');
    const toolbar_buttons = api.settings.get('visible_toolbar_buttons');
    const is_groupchat = el.model.get('type') === CHATROOMS_TYPE;
    const {
        call: show_call_button,
        emoji: show_emoji_button,
        fileupload: show_fileupload_button,
        location: show_location_button,
        spoiler: show_spoiler_button,
    } = toolbar_buttons;
    const show_send_button = api.settings.get('show_send_button');
    const show_toolbar = api.settings.get('show_toolbar');

    return html`<converse-reply-preview .model="${el.model}"></converse-reply-preview><form class="chat-message-form" @submit="${/** @param {SubmitEvent} ev */ (ev) => el.onFormSubmitted(ev)}">${
                show_toolbar
                    ? html`<converse-chat-toolbar class="btn-toolbar chat-toolbar no-text-select" .model="${el.model}" ?composing_spoiler="${composing_spoiler}" ?is_groupchat="${is_groupchat}" ?show_call_button="${show_call_button}" ?show_emoji_button="${show_emoji_button}" ?show_fileupload_button="${show_fileupload_button}" ?show_location_button="${show_location_button}" ?show_send_button="${show_send_button}" ?show_spoiler_button="${show_spoiler_button}" ?show_toolbar="${show_toolbar}" message_limit="${message_limit}"></converse-chat-toolbar>`
                    : ''
            } <input type="text" enterkeyhint="send" placeholder="${label_spoiler_hint || ''}" .value="${el.model.get('draft_hint') ?? ''}" @change="${
                    /** @param {Event} ev */ (ev) =>
                        u.safeSave(el.model, { draft_hint: /** @type {HTMLInputElement} */ (ev.target).value })
                }" class="${composing_spoiler ? '' : 'hidden'} spoiler-hint"><div class="chat-rich"><div class="chat-textarea chat-rich__editable ${el.is_empty ? 'is-empty' : ''} ${el.model.get('correcting') ? 'correcting' : ''} ${show_send_button ? 'chat-textarea-send-button' : ''} ${composing_spoiler ? 'spoiler' : ''}" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${label_message}" data-placeholder="${label_message}" @focusin="${() => el.ensureEditor()}" @focusout="${/** @param {FocusEvent} ev */ (ev) => el.onEditorFocusOut(ev)}" @drop="${/** @param {DragEvent} ev */ (ev) => el.onDrop(ev)}" @keydown="${/** @param {KeyboardEvent} ev */ (ev) => el.onKeyDown(ev)}" @keyup="${/** @param {KeyboardEvent} ev */ (ev) => el.onKeyUp(ev)}" @paste="${/** @param {ClipboardEvent} ev */ (ev) => el.onPaste(ev)}"></div>${el.typeahead.is_open ? tplTypeahead(el.typeahead) : ''}</div></form>`;
};
